// A dependency that tries to reach a builtin its policy forbids. Import policy
// (LLP 0013 Policy surface 3) is the primary gate for builtins: withholding the
// `fs` endowment is not enough if the package can still `require('fs')`.
module.exports.tryImport = function tryImport() {
  try {
    var fs = require("fs");
    return "IMPORTED:" + typeof fs.readFileSync;
  } catch (e) {
    return "IMPORT-DENIED";
  }
};
